-- ============================================================
-- Migrasi 0096 — Website Articles: kolom tambahan + baca publik + seed
--
-- Tabel website_articles (beserta website_banners & portal_information)
-- SUDAH dibuat oleh rancangan migrasi 0010 dan sudah berjalan di
-- database, tetapi selama ini kosong dan tidak terhubung: Admin
-- Portal menyimpan konten di memori browser, website membaca
-- artikel hardcode di kode. Migrasi ini melengkapi fondasi itu:
--   1. Kolom penulis_peran + kutipan (dipakai kartu & modal baca
--      di website publik, belum ada di skema 0010).
--   2. Kebijakan baca publik (anon) khusus artikel yang sudah
--      tayang — jalur utama aplikasi tetap lewat endpoint server.
--   3. Seed 14 artikel yang selama ini tampil di website
--      (8 SMK + 6 SMP, status Terbit) agar website tidak kosong
--      saat sumber datanya beralih ke database.
-- Sesudah migrasi ini: Admin Portal (CRUD) -> website_articles ->
-- website publik SMP & SMK, satu arah, per jenjang.
-- ============================================================

alter table public.website_articles
  add column if not exists penulis_peran text not null default '',
  add column if not exists kutipan_teks text not null default '',
  add column if not exists kutipan_penulis text not null default '';

comment on column public.website_articles.penulis_peran is
  'Peran penulis yang tampil di website publik, mis. Sekretariat SPMB.';
comment on column public.website_articles.kutipan_teks is
  'Kutipan sorotan di modal baca website publik (opsional).';
comment on column public.website_articles.kutipan_penulis is
  'Nama pemberi kutipan sorotan (opsional).';

drop policy if exists "Artikel website dibaca publik" on public.website_articles;
create policy "Artikel website dibaca publik"
  on public.website_articles for select
  to anon, authenticated
  using (
    deleted_at is null
    and (
      status = 'Terbit'
      or (status = 'Terjadwal' and tanggal_jadwal is not null and tanggal_jadwal <= now())
    )
  );

-- ============================================================
-- Seed: 14 artikel existing dari website (status Terbit)
-- ============================================================
insert into public.website_articles
  (jenjang, judul, subjudul, slug, kategori, status, tanggal_terbit, penulis, penulis_peran, ringkasan, isi_html, gambar_url, featured, tags, kutipan_teks, kutipan_penulis, views)
values
  ('SMK', 'SPMB 2027/2028 Dibuka: 7 Rombel, 3 Gelombang Pendaftaran', '', 'spmb-2027-2028-dibuka-7-rombel', 'Pengumuman', 'Terbit', '2026-10-04'::date, 'Panitia SPMB', 'Sekretariat SPMB 2027', 'Penerimaan murid baru tahun ajaran 2027/2028 resmi dibuka dengan tiga gelombang dan biaya registrasi hanya Rp50.000. Kuota terbatas hanya tujuh rombel — ditambah pendaftaran inden untuk 2028/2029.', '<p>SMK IT Attaqwa 9 Babelan secara resmi membuka Penerimaan Murid Baru (SPMB) untuk Tahun Ajaran 2027/2028. Mengusung moto "Unggul dalam IMTAQ, Terdepan dalam IPTEK", proses seleksi tahun ini dirancang untuk menyaring calon santri yang siap berkomitmen mendalami keahlian vokasi industri dan pembinaan akhlak Islami.</p><p>Sesuai ketetapan musyawarah yayasan dan manajemen sekolah, kuota penerimaan tahun ini dibatasi tepat 7 rombongan belajar (rombel) yang terbagi ke dalam 6 konsentrasi keahlian: Akuntansi &amp; Keuangan Lembaga (AKL), Otomatisasi &amp; Tata Kelola Perkantoran (OTKP), Teknik &amp; Bisnis Sepeda Motor (TBSM), Teknik Kendaraan Ringan (TKR), Teknik Komputer &amp; Jaringan (TKJ), serta Desain Komunikasi Visual (DKV).</p><p>Pendaftaran dibuka dalam 3 gelombang bertahap dengan biaya registrasi terjangkau Rp50.000 (gratis khusus bagi yatim dan santri berprestasi): Gelombang 1 (Oktober – Desember 2026), Gelombang 2 (Januari – Maret 2027), dan Gelombang Tambahan (April – Juni 2027 jika kuota masih tersedia). Calon pendaftar juga dapat memanfaatkan fasilitas pendaftaran inden untuk Tahun Ajaran 2028/2029.</p><p>Calon wali murid dan santri dapat melakukan pendaftaran secara mandiri melalui portal SPMB Online di website ini atau hadir langsung ke sekretariat SPMB di Kampus SMK IT Attaqwa 9, Pondok Pesantren Attaqwa Putri/Putra Kavling Ujung Harapan, Bahagia, Babelan, Kabupaten Bekasi pada hari kerja.</p>', '/asset/SMK/news-spmb.webp', true, array['SPMB', 'Pendaftaran', 'Gelombang 1', 'Beasiswa Tahfidz']::text[], 'Kami berkomitmen menjaga rasio ideal pembelajaran kejuruan dengan membatasi kuota hanya 7 rombel agar setiap santri mendapatkan porsi praktik bengkel dan lab komputer secara maksimal.', 'Ketua Panitia SPMB 2027/2028', 1420),
  ('SMK', 'Mengenal Deep Learning: Cara Baru Belajar di Kurikulum Merdeka', '', 'mengenal-deep-learning-kurikulum-merdeka', 'Akademik', 'Terbit', '2026-09-28'::date, 'Tim Kurikulum', 'Pengembang Kurikulum Vokasi', 'Bukan sekadar menghafal — bagaimana pendekatan pembelajaran mendalam mengubah cara siswa memahami pelajaran vokasi dan pemecahan masalah kontekstual.', '<p>Penerapan Kurikulum Merdeka di SMK IT Attaqwa 9 diperkaya dengan pendekatan Deep Learning (pembelajaran mendalam). Berbeda dari metode ceramah tradisional yang berfokus pada hafalan teori, deep learning menempatkan siswa sebagai subjek aktif yang mengonstruksi pemahamannya melalui tiga pilar utama: Mindful Learning, Meaningful Learning, dan Joyful Learning.</p><p>Dalam konteks kejuruan teknik dan manajemen, pendekatan ini diwujudkan melalui pembelajaran berbasis proyek nyata (Project-Based Learning). Sebagai contoh, siswa jurusan TKJ tidak hanya diajarkan konfigurasi routing di atas kertas, melainkan ditantang mendesain dan mengamankan topologi jaringan LAN/WAN berstandar enterprise yang siap tahan terhadap simulasi cyber attack.</p><p>Begitu pula di bidang Desain Komunikasi Visual (DKV), santri membedah studi kasus identitas merek UMKM lokal, melakukan riset audiens pengguna, merancang antarmuka UI/UX aplikasi, hingga mempresentasikan purwarupa desain di hadapan dewan guru dan praktisi industri tamu.</p><p>Hasil evaluasi internal menunjukkan bahwa santri yang belajar dengan metode pembelajaran mendalam memiliki daya nalar kritis lebih tajam, daya ingat konsep jangka panjang yang lebih kokoh, serta kepercayaan diri tinggi saat menjalani Uji Kompetensi Kejuruan (UKK).</p>', '/asset/SMK/news-deeplearning.webp', false, array['Kurikulum Merdeka', 'Deep Learning', 'Metode Belajar', 'Vokasi']::text[], 'Pendidikan vokasi yang bermakna bukan diukur dari berapa banyak rumus yang dihafal, melainkan seberapa tanggap siswa memecahkan masalah riil di bengkel kerja.', 'Wakil Kepala Sekolah Bidang Kurikulum', 890),
  ('SMK', 'BLK Komunitas: Jembatan Sekolah Menuju Dunia Industri', '', 'blk-komunitas-jembatan-sekolah-ke-dunia-industri', 'Kegiatan', 'Terbit', '2026-09-20'::date, 'Humas DUDIKA', 'Divisi Kemitraan Industri', 'Gedung Balai Latihan Kerja Komunitas Kemnaker RI di SMK IT Attaqwa 9 menjadi pusat praktik kejuruan berstandar industri nasional.', '<p>Keberadaan gedung Balai Latihan Kerja (BLK) Komunitas bantuan Kementerian Ketenagakerjaan Republik Indonesia (Kemnaker RI) menjadi nilai pembeda strategis bagi SMK IT Attaqwa 9. Berdiri mandiri di area kampus sekolah, fasilitas ini difungsikan sebagai pusat pelatihan dan sertifikasi kompetensi terpadu.</p><p>Gedung BLK dilengkapi dengan peralatan uji mesin terkini, toolset otomotif injeksi berstandar APM, engine scanner multifungsi untuk roda dua dan empat, serta laboratorium multimedia komputer spesifikasi tinggi untuk simulasi rendering dan pemrograman jaringan.</p><p>Melalui skema link and match dengan Dunia Usaha, Dunia Industri, dan Dunia Kerja (DUDIKA), kurikulum pelatihan di BLK diselaraskan langsung dengan kebutuhan industri manufaktur di kawasan industri Cikarang dan Karawang.</p><p>Setiap tahunnya, santri tingkat akhir mengikuti sertifikasi profesi di BLK sebelum diberangkatkan menuju program Praktik Kerja Industri (Prakerin) selama 3 hingga 6 bulan di perusahaan mitra rekanan resmi sekolah.</p>', '/asset/SMK/news-blk.webp', false, array['BLK Komunitas', 'Kemnaker RI', 'Prakerin', 'Fasilitas Bengkel']::text[], 'Fasilitas BLK Komunitas memastikan santri tidak canggung saat terjun ke lingkungan pabrik atau kantor industri modern.', 'Kepala Bengkel BLK Komunitas', 960),
  ('SMK', 'Juara 1 LKS IT Network System Administration Kab. Bekasi', '', 'juara-1-lks-it-network-kabupaten-bekasi', 'Prestasi', 'Terbit', '2026-09-15'::date, 'Humas Sekolah', 'Biro Prestasi & Publikasi', 'Siswa kompetensi keahlian TKJ SMK IT Attaqwa 9 berhasil membuktikan keunggulan skill di ajang bergengsi Lomba Kompetensi Siswa (LKS) IT Network.', '<p>Kabar membanggakan datang dari panggung Lomba Kompetensi Siswa (LKS) SMK Tingkat Kabupaten Bekasi Tahun 2026. Santri perwakilan SMK IT Attaqwa 9 sukses meraih Juara 1 pada bidang lomba IT Network System Administration setelah menyisihkan puluhan peserta dari sekolah negeri dan swasta se-Kabupaten Bekasi.</p><p>Pada kompetisi yang berlangsung selama dua hari penuh tersebut, peserta diuji dalam skenario instalasi server enterprise Debian/CentOS, konfigurasi routing BGP/OSPF MikroTik &amp; Cisco, deployment DNS/Web/Mail Server secured dengan SSL, serta pemecahan masalah jaringan dalam batas waktu ketat.</p><p>Ketelitian konfigurasi, efisiensi dokumentasi teknis, dan etika kerja profesional santri SMK IT Attaqwa 9 mendapat apresiasi tinggi dari dewan juri yang beranggotakan praktisi industri telekomunikasi dan akademisi perguruan tinggi.</p><p>Dengan raihan medali emas ini, kontingen SMK IT Attaqwa 9 berhak melaju mewakili Kabupaten Bekasi menuju gelaran LKS SMK Tingkat Provinsi Jawa Barat yang akan digelar pada awal tahun depan.</p>', '/asset/SMK/ig-4.webp', false, array['LKS SMK', 'TKJ', 'Juara 1', 'Kabupaten Bekasi', 'Prestasi']::text[], 'Alhamdulillah, pembinaan intensif di lab jaringan dan kebiasaan berdoa sebelum tanding menjadi kunci kemenangan di ajang LKS ini.', 'Pembimbing Kontingen LKS SMK IT Attaqwa 9', 1680),
  ('SMK', 'Program Tahfidz Yanbu''a: Target Hafalan Setiap Semester', '', 'program-tahfidz-yanbua-target-hafalan-semester', 'Keagamaan', 'Terbit', '2026-09-12'::date, 'Asatidz Tahfidz', 'Koordinator Tahfidz Yanbu''a', 'Metode Yanbu''a membuat setoran hafalan Qur''an menjadi pembiasaan yang terukur, tartil, dan menyenangkan bagi santri sekolah kejuruan.', '<p>Di tengah padatnya jadwal praktik kejuruan di bengkel dan lab komputer, SMK IT Attaqwa 9 tetap menempatkan pembinaan Al-Qur''an sebagai ruh utama pendidikan. Program tahfidz di sekolah ini dibimbing menggunakan metode Yanbu''a yang terkenal dengan penekanan pada ketepatan makharijul huruf, tajwid berstandar sanad, dan pembiasaan tartil.</p><p>Setiap santri dikelompokkan ke dalam halaqoh kecil beranggotakan 10–12 orang yang didampingi oleh satu ustadz/ustadzah pembimbing. Kegiatan setoran hafalan (ziyadah) dan pengulangan rutin (murojaah) dilaksanakan pada pagi hari sebelum KBM dimulai serta ba''da sholat Ashar berjamaah.</p><p>Program ini memiliki target kelulusan hafalan terstruktur setiap semesternya, mulai dari Juz 30, Juz 1, hingga Juz 29 dan surat-surat pilihan seperti Yasin, Al-Waqiah, Al-Mulk, dan Ar-Rahman. Bagi santri yang memiliki hafalan di atas 3 juz, sekolah menyediakan program kelas akselerasi tahfidz khusus.</p><p>Kemandirian dan ketahanan mental santri diperkuat melalui tradisi Sima''an Qur''an bulanan, di mana santri melantunkan hafalan di hadapan teman sebaya dan asatidz tanpa melihat mushaf.</p>', '/asset/SMK/ig-3.webp', false, array['Tahfidz', 'Yanbua', 'Karakter Santri', 'Simaan Quran']::text[], 'Menjadi ahli teknologi bukan alasan untuk jauh dari Al-Qur''an. Keduanya justru saling melengkapi membentuk generasi tangguh berakhlak mulia.', 'Koordinator Program Keagamaan', 740),
  ('SMK', 'Showcase Portofolio: Desain UI/UX & Animasi Santri DKV', '', 'showcase-portofolio-desain-uiux-animasi-dkv', 'Kegiatan', 'Terbit', '2026-08-28'::date, 'Jurusan DKV', 'Kaprog Keahlian DKV', 'Pameran karya digital santri vokasi siap industri: prototipe aplikasi mobile interaktif, desain branding, dan kreasi visual berstandar agensi.', '<p>Santri Konsentrasi Keahlian Desain Komunikasi Visual (DKV) SMK IT Attaqwa 9 menyelenggarakan pameran karya digital bertajuk "Kreativitas Santri untuk Negeri". Acara tahunan ini memamerkan ratusan karya orisinal mulai dari rancangan antarmuka pengguna (UI/UX Design), identitas visual korporat, video iklan komersial, hingga animasi pendek 2D &amp; 3D.</p><p>Salah satu karya yang menyita perhatian adalah prototipe aplikasi mobile sistem donasi masjid digital dan sistem manajemen perpustakaan pesantren karya siswa kelas XI DKV. Prototipe tersebut dirancang lengkap dengan user flow terstruktur, design system berbasis komponen rapi di Figma, serta interaksi mikro yang intuitif.</p><p>Di bidang grafis cetak dan digital, santri memamerkan poster edukasi sosial, kemasan produk UMKM, dan layout majalah sekolah. Seluruh karya dinilai secara langsung oleh kurator tamu dari studio kreatif rekanan industri.</p><p>Portofolio digital yang terkumpul diunggah ke platform Behance dan Dribbble resmi sekolah untuk mempermudah perusahaan mitra merekrut lulusan DKV saat kelulusan.</p>', '/asset/SMK/ig-2.webp', false, array['DKV', 'UI/UX Design', 'Motion Graphic', 'Portofolio', 'Karya Digital']::text[], 'Karya santri DKV membuktikan bahwa nilai estetika modern dan pesan dakwah positif dapat berpadu menghasilkan produk desain bernilai jual tinggi.', 'Instruktur Desain Komunikasi Visual', 1120),
  ('SMK', 'Jadwal Tes Gelombang I SPMB 2027/2028 & Alur Seleksi', '', 'jadwal-tes-gelombang-1-spmb-2027-2028', 'Pengumuman', 'Terbit', '2026-08-15'::date, 'Panitia SPMB', 'Biro Seleksi Akademik', 'Tes seleksi gelombang pertama dilaksanakan Ahad, 27 Desember 2026. Pengumuman hasil seleksi 30 Desember 2026.', '<p>Bagi calon santri dan orang tua yang telah menyelesaikan formulir pendaftaran Gelombang I SPMB Tahun Ajaran 2027/2028, berikut jadwal resmi pelaksanaan tahapan seleksi masuk:</p><p>1. Pelaksanaan Tes CBT Mandiri: Ahad, 27 Desember 2026 (Pukul 08.00 – 10.30 WIB di Lab Komputer SMK IT Attaqwa 9). Materi mencakup Tes Potensi Akademik (Matematika Dasar, Bahasa Indonesia, Bahasa Inggris) dan Pemahaman Agama Islam.</p><p>2. Tes Baca Al-Qur''an &amp; Tahfidz: Ahad, 27 Desember 2026 (Pukul 10.45 – 12.00 WIB bersama Asatidz Penguji).</p><p>3. Wawancara Komitmen Wali Santri: Dilaksanakan paralel bersama jajaran pimpinan sekolah untuk menyelaraskan visi pendidikan pesantren.</p><p>4. Pengumuman Kelulusan Resmi: Rabu, 30 Desember 2026 melalui portal SPMB Online dan pesan WhatsApp panitia.</p><p>Peserta wajib membawa kartu pendaftaran, berpakaian muslim/muslimah rapi dan sopan, serta hadir 30 menit sebelum sesi dimulai.</p>', '/asset/SMK/ig-1.webp', false, array['SPMB', 'Jadwal Tes', 'CBT Seleksi', 'Wawancara']::text[], '', '', 910),
  ('SMK', 'Mempertahankan Akreditasi A: Komitmen Mutu Vokasi Berkelanjutan', '', 'akreditasi-a-komitmen-mutu-vokasi-berkelanjutan', 'Kegiatan', 'Terbit', '2026-08-01'::date, 'Biro Penjaminan Mutu', 'Tim Akreditasi BAN-SM', 'Hasil evaluasi BAN-SM mengukuhkan SMK IT Attaqwa 9 sebagai sekolah vokasi berpredikat Unggul dengan nilai kepatuhan standar industri tinggi.', '<p>Badan Akreditasi Nasional Sekolah/Madrasah (BAN-SM) secara resmi menetapkan kembali status Akreditasi A (Unggul) bagi SMK IT Attaqwa 9 dengan skor penilaian mutu 94 poin dari 100.</p><p>Pencapaian ini merupakan buah dari pemenuhan delapan standar nasional pendidikan yang ditopang oleh fasilitas praktik bengkel BLK Komunitas, sarana lab komputer ber-AC, rasio guru tersertifikasi kompetensi, serta jejaring kerja sama industri yang aktif.</p><p>Tim asesor memberikan apresiasi khusus terhadap keterpaduan nilai keagamaan pesantren dengan penguasaan teknologi mutakhir (IMTAQ &amp; IPTEK) yang tercermin dalam etos kerja santri.</p><p>Manajemen sekolah berkomitmen untuk terus meningkatkan investasi fasilitas dan pelatihan guru agar standar mutu lulusan semakin relevan dengan tuntutan revolusi industri.</p>', '/asset/SMK/gedung-smk.webp', false, array['Akreditasi A', 'Penjaminan Mutu', 'Fasilitas', 'BAN-SM']::text[], '', '', 1240),
  ('SMP', 'SPMB 2027/2028 Dibuka: 7 Rombel, 3 Gelombang Pendaftaran', '', 'spmb-2027-2028-smp-it-bca-dibuka', 'Pengumuman', 'Terbit', '2026-10-04'::date, 'Panitia SPMB', 'Sekretariat SPMB BCA', 'Penerimaan murid baru tahun ajaran 2027/2028 resmi dibuka dengan tiga gelombang dan biaya registrasi hanya Rp50.000. Kuota terbatas hanya tujuh rombel — ditambah pendaftaran inden untuk 2028/2029.', '<p>SMP IT Bina Cendekia Assalam (BCA) Babelan secara resmi membuka Seleksi Penerimaan Murid Baru (SPMB) Tahun Ajaran 2027/2028. Mengusung tagline "Alqur''an &amp; Akhlaknya Terpuji, Prestasi Akademiknya Teruji", proses seleksi tahun ini siap menyaring calon santri yang ingin mendalami kurikulum nasional Diknas yang dipadukan dengan pembiasaan karakter Islami.</p><p>Sesuai keputusan yayasan, kuota penerimaan tahun ini dibatasi 7 rombongan belajar (rombel) yang terbagi ke dalam kelas khusus putra dan kelas khusus putri. Pendaftaran dibuka dalam 3 gelombang bertahap dengan biaya registrasi hanya Rp50.000 (gratis bagi siswa yatim dan berprestasi).</p><p>Orang tua dan calon siswa dapat mendaftar secara online melalui portal SPMB atau datang langsung ke sekretariat di Ujung Harapan, Musholla Assalam, Kelurahan Bahagia, Kecamatan Babelan, Kabupaten Bekasi pada jam kerja.</p>', null, true, array['SPMB', 'Pendaftaran', 'Kelas Gender', 'Beasiswa']::text[], 'Kami menjaga rasio ideal pembelajaran kelas gender agar setiap santri putra dan putri mendapatkan pendampingan murobbi yang maksimal.', 'Ketua Panitia SPMB SMP IT BCA', 1280),
  ('SMP', 'Milad ke-6: Enam Tahun SMP IT Bina Cendekia Assalam Mendidik Generasi', '', 'milad-ke-6-enam-tahun-smp-it-bina-cendekia-assalam', 'Kegiatan', 'Terbit', '2026-04-16'::date, 'Humas Sekolah', 'Biro Publikasi & Dokumentasi', 'Perayaan enam tahun berdirinya sekolah — dari angkatan pertama hingga mendidik lebih dari 1000 santri alumni berprestasi.', '<p>SMP IT Bina Cendekia Assalam memperingati milad ke-6 sejak didirikan pada 16 April 2021 di bawah naungan مؤسسة دار القهار. Acara syukuran ini dihadiri oleh jajaran pembina yayasan, dewan guru, komite orang tua, serta para alumni.</p><p>Dalam kurun waktu enam tahun, SMP IT BCA telah menorehkan berbagai capaian membanggakan, mulai dari akreditasi unggul, implementasi penuh 7 program unggulan, hingga melahirkan santri-santri penghafal Al-Qur''an yang berprestasi di tingkat kabupaten dan provinsi.</p><p>Pada momen milad ini, sekolah juga meluncurkan program Beasiswa Milad BCA ke-6 berupa pembebasan uang pangkal dan subsidi SPP bagi santri berprestasi dan yatim piatu.</p>', null, false, array['Milad BCA', 'Sejarah', 'Generasi Qurani', 'Ulang Tahun']::text[], 'Enam tahun adalah tonggak kematangan kurikulum dan pembiasaan adab yang terus kami jaga.', 'Kepala SMP IT BCA', 940),
  ('SMP', 'Mengenal Sekolah Berbasis Kelas Gender: Mengapa Lebih Fokus?', '', 'mengenal-sekolah-berbasis-kelas-gender', 'Akademik', 'Terbit', '2026-09-28'::date, 'Tim Akademik', 'Divisi Kurikulum CTL', 'Putra belajar dengan putra, putri dengan putri — bagaimana konsep kelas gender membuat proses KBM lebih optimal dan pergaulan terjaga.', '<p>Pemisahan kelas putra dan putri di SMP IT Bina Cendekia Assalam didasarkan pada pemahaman mendalam atas perbedaan psikologi perkembangan remaja. Di usia SMP (12–15 tahun), anak mengalami transisi pubertas yang membutuhkan lingkungan kondusif tanpa tekanan sosial antar-lawan jenis.</p><p>Dengan metode Contextual Teaching and Learning (CTL), guru dapat menyesuaikan gaya mengajar: kelas putra diberikan stimulasi tantangan gerak dan diskusi aktif, sementara kelas putri difokuskan pada kedalaman analisis dan kerja sama suportif.</p><p>Hasilnya, santri lebih percaya diri bertanya, berani mengemukakan pendapat, dan tidak merasa canggung saat belajar di dalam kelas.</p>', null, false, array['Kelas Gender', 'Metode CTL', 'Pendidikan Remaja', 'Fitrah']::text[], 'Kelas gender bukan membatasi, melainkan memberikan ruang tumbuh yang paling aman dan sesuai fitrah psikologis remaja.', 'Konsultan Psikologi Pendidikan', 860),
  ('SMP', 'Program Tahfidz Yanbu''a: Target Hafalan Setiap Semester', '', 'program-tahfidz-yanbua-target-hafalan-terukur', 'Akademik', 'Terbit', '2026-09-12'::date, 'Asatidz Tahfidz', 'Koordinator Tahfidz Yanbu''a', 'Metode Yanbu''a membuat setoran hafalan Qur''an menjadi pembiasaan yang ringan, tartil, dan terukur bagi siswa tingkat SMP.', '<p>Metode Yanbu''a menekankan ketelitian makhraj huruf dan hukum tajwid sebelum santri menambah jumlah hafalan. Di SMP IT BCA, setiap santri memiliki buku mutaba''ah harian untuk mencatat capaian ziyadah dan murojaah.</p><p>Program ini didukung oleh tradisi Sima''an Qur''an bulanan, di mana santri membaca hafalan satu juz sekali duduk di hadapan asatidz dan teman sekelas tanpa melihat mushaf.</p><p>Dengan metode terstruktur ini, santri mampu mencapai target hafalan Juz 30, Juz 29, dan surat-surat pilihan saat menyelesaikan pendidikan jenjang SMP.</p>', null, false, array['Tahfidz', 'Yanbua', 'Simaan', 'Adab Quran']::text[], '', '', 710),
  ('SMP', 'Entrepreneur Day: Melatih Jiwa Wirausaha dan Kreativitas Santri', '', 'entrepreneur-day-melatih-jiwa-wirausaha-sejak-dini', 'Kegiatan', 'Terbit', '2026-09-05'::date, 'Kesiswaan', 'Koordinator Talent Development', 'Siswa mempraktikkan ilmu kewirausahaan lewat bazar produk kuliner dan kriya mandiri di lingkungan sekolah.', '<p>Agenda tahunan Entrepreneur Day SMP IT BCA kembali digelar meriah. Seluruh kelompok kelas santri putra dan putri merancang proposal produk, menghitung harga pokok produksi, mendesain kemasan, hingga memasarkan produk olahan kuliner dan karya kerajinan tangan.</p><p>Kegiatan ini melatih kecakapan komunikasi bisnis, kejujuran dalam berdagang, pembagian tugas tim, serta pengelolaan laba usaha secara syariah.</p><p>Sebagian keuntungan penjualan disalurkan ke kas infaq sosial santri untuk melatih kepedulian berbagi.</p>', null, false, array['Entrepreneur Day', 'Bazar', 'Kewirausahaan', 'Kreativitas']::text[], '', '', 650),
  ('SMP', 'Public Speaking with School @america: Santri Percaya Diri Tampil', '', 'public-speaking-with-school-america', 'Kegiatan', 'Terbit', '2026-08-28'::date, 'Tim Bahasa', 'Koordinator Unggul Bahasa', 'Program unggul bahasa melatih santri tampil fasih dan percaya diri berbahasa Inggris di depan panggung publik.', '<p>Bekerja sama dengan platform edukasi School @america, santri SMP IT BCA mengikuti lokakarya intensif teknik presentasi dan pidato bahasa Inggris.</p><p>Santri dilatih mengatasi demam panggung, menyusun argumen terstruktur, menguasai intonasi suara, serta bahasa tubuh yang meyakinkan.</p><p>Sesi ditutup dengan lomba pidato bahasa Inggris antar-kelas dengan dewan juri penutur asli (*native speaker*).</p>', null, false, array['Public Speaking', 'School @america', 'Bahasa Inggris', 'Prestasi']::text[], '', '', 790)
